from itertools import combinations, product
import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if mandatory & blocked:
            return {"error": "impossible"}
        available = [j for j in jobs if j["id"] not in blocked]
        best_ids = None
        best_value = None
        for subset in combinations(available, k):
            ids = tuple(sorted(j["id"] for j in subset))
            idset = set(ids)
            if not mandatory <= idset:
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            valid = True
            for start in {j["start"] for j in subset}:
                if sum(j["start"] <= start < j["end"] for j in subset) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(j["value"] for j in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     (ids < best_ids if tie == "smallest" else ids > best_ids))):
                best_value, best_ids = value, ids
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(n, d, mode):
        if mode == "half_up":
            return (2 * n + d) // (2 * d)
        return n // d

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)
        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        versions = {
            name: {row["version"]: row for row in packages[name]}
            for name in names
        }
        choices = [[None] + sorted(versions[name]) for name in names]
        best_key = None
        best = None

        for values in product(*choices):
            install = {name: version for name, version in zip(names, values)
                       if version is not None}
            if any(version in blocked.get(name, []) or
                   (name in pins and pins[name] != version)
                   for name, version in install.items()):
                continue
            graph = {}
            active = set()
            finished = set()
            cyclic = False

            def visit(name, low, high):
                nonlocal cyclic
                version = install.get(name)
                if version is None or not low <= version <= high:
                    return False
                if name in active:
                    cyclic = True
                    return False
                if name in finished:
                    return True
                row = versions[name].get(version)
                if row is None:
                    return False
                active.add(name)
                active.add(name)
                edges = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    edges.append(other)
                    if not visit(other, dep["min"], dep["max"]):
                        active.remove(name)
                        return False
                active.remove(name)
                finished.add(name)
                graph[name] = edges
                return True

            ok = True
            for name, bounds in data["roots"].items():
                if not visit(name, bounds[0], bounds[1]):
                    ok = False
                    break
            if not ok or cyclic or set(install) != finished:
                continue
            key = tuple(install.get(name, -1) for name in names)
            if best_key is None or key < best_key:
                best_key, best = key, install
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        initial_mask = bit.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        distance = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distance.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    options.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                for duration, coupons_left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    nxt_mask = mask | bit.get(nxt, 0)
                    nxt_state = (nxt, nxt_mask, coupons_left)
                    if arrival < distance.get(nxt_state, float("inf")):
                        distance[nxt_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, nxt_mask, coupons_left))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _interval_solver(1, "smallest"),
    "component_02": _interval_solver(2, "smallest"),
    "component_03": _interval_solver(1, "largest"),
    "component_04": _interval_solver(2, "largest"),
    "component_05": _interval_solver(1, "smallest"),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
